select e.id as "id", e.org_id as "org_id", o.name as "name",
       e.parent_org_id as "parent_id", o.code as "code", o.org_source_id as "source_org_id",
       nvl(x.accountCount,0) as "accountCount",
       nvl(x.cnt_d01,0) as "基本存款账户", nvl(x.cnt_d02,0) as "一般存款账户",
       nvl(x.cnt_d03,0) as "专用存款账户", nvl(x.cnt_d04,0) as "临时存款账户",
       nvl(x.cnt_d05,0) as "其他存款账户", nvl(x.cnt_d06,0) as "保证金账户",
       nvl(y.legal_cnt,0) as "法人公司数量", nvl(y.nonlegal_cnt,0) as "非法人公司数量"
from iuap_apdoc_basedoc.org_epm_orginization_ext e
join iuap_apdoc_basedoc.org_epm_organizations o on o.id = e.org_id
left join (
    select node_id, count(acct_code) as accountCount,
           sum(case when purpose_code='D01' then 1 else 0 end) as cnt_d01,
           sum(case when purpose_code='D02' then 1 else 0 end) as cnt_d02,
           sum(case when purpose_code='D03' then 1 else 0 end) as cnt_d03,
           sum(case when purpose_code='D04' then 1 else 0 end) as cnt_d04,
           sum(case when purpose_code='D05' then 1 else 0 end) as cnt_d05,
           sum(case when purpose_code='D06' then 1 else 0 end) as cnt_d06
      from ( select cl.anc_member_id as node_id, acc.acct_code, max(acc.purpose_code) as purpose_code
               from (
        select e0.org_id as desc_org_id, e0.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0  where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
        union all
        select e0.org_id as desc_org_id, e1.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
        union all
        select e0.org_id as desc_org_id, e2.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
        union all
        select e0.org_id as desc_org_id, e3.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
        union all
        select e0.org_id as desc_org_id, e4.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e4 on e4.id=e3.parent_org_id and e4.dr=0 and e4.ytenant_id='jd4ofb7k' and e4.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
        union all
        select e0.org_id as desc_org_id, e5.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e4 on e4.id=e3.parent_org_id and e4.dr=0 and e4.ytenant_id='jd4ofb7k' and e4.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e5 on e5.id=e4.parent_org_id and e5.dr=0 and e5.ytenant_id='jd4ofb7k' and e5.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
        union all
        select e0.org_id as desc_org_id, e6.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e4 on e4.id=e3.parent_org_id and e4.dr=0 and e4.ytenant_id='jd4ofb7k' and e4.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e5 on e5.id=e4.parent_org_id and e5.dr=0 and e5.ytenant_id='jd4ofb7k' and e5.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e6 on e6.id=e5.parent_org_id and e6.dr=0 and e6.ytenant_id='jd4ofb7k' and e6.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
        union all
        select e0.org_id as desc_org_id, e7.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e4 on e4.id=e3.parent_org_id and e4.dr=0 and e4.ytenant_id='jd4ofb7k' and e4.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e5 on e5.id=e4.parent_org_id and e5.dr=0 and e5.ytenant_id='jd4ofb7k' and e5.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e6 on e6.id=e5.parent_org_id and e6.dr=0 and e6.ytenant_id='jd4ofb7k' and e6.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e7 on e7.id=e6.parent_org_id and e7.dr=0 and e7.ytenant_id='jd4ofb7k' and e7.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
               ) cl
               join iuap_apdoc_basedoc.org_epm_organizations o2 on o2.id = cl.desc_org_id
               join (select a.orgid, a.code as acct_code,
                            case when zd.code='JYSK0002' then z.code end as purpose_code
                       from iuap_apdoc_basedoc.org_fin_bankacct a
                       left join iuap_apdoc_basedoc.org_fin_bankacct_character_define_1 d on d.id=a.defineCharacter
                       left join iuap_apdoc_basedoc.bd_cust_doc z on z.id=d.vcol8 and z.dr=0 and z.ytenant_id=a.ytenant_id
                       left join iuap_apdoc_basedoc.bd_cust_doc_def zd on zd.id=z.custdocdefid and zd.dr=0
                      where a.dr=0 and a.ytenant_id='jd4ofb7k'
                        and nvl(a.acctstatus,0) <> 1
                        and nvl(a.acctopentype,-1) <> 2
                        and a.accountOpenDate >= '2026-01-01'
                        and a.accountOpenDate <= '2026-09-22'
                      ) acc on acc.orgid = o2.org_source_id
              group by cl.anc_member_id, acc.acct_code ) t
     group by node_id ) x on x.node_id = e.id
left join (
    select node_id, sum(is_legal) as legal_cnt,
           sum(case when is_legal=0 then 1 else 0 end) as nonlegal_cnt
      from ( select cl.anc_member_id as node_id, org.org_pk, max(org.is_legal) as is_legal
               from (
                select e0.org_id as desc_org_id, e0.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0  where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
                union all
                select e0.org_id as desc_org_id, e1.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
                union all
                select e0.org_id as desc_org_id, e2.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
                union all
                select e0.org_id as desc_org_id, e3.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
                union all
                select e0.org_id as desc_org_id, e4.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e4 on e4.id=e3.parent_org_id and e4.dr=0 and e4.ytenant_id='jd4ofb7k' and e4.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
                union all
                select e0.org_id as desc_org_id, e5.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e4 on e4.id=e3.parent_org_id and e4.dr=0 and e4.ytenant_id='jd4ofb7k' and e4.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e5 on e5.id=e4.parent_org_id and e5.dr=0 and e5.ytenant_id='jd4ofb7k' and e5.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
                union all
                select e0.org_id as desc_org_id, e6.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e4 on e4.id=e3.parent_org_id and e4.dr=0 and e4.ytenant_id='jd4ofb7k' and e4.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e5 on e5.id=e4.parent_org_id and e5.dr=0 and e5.ytenant_id='jd4ofb7k' and e5.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e6 on e6.id=e5.parent_org_id and e6.dr=0 and e6.ytenant_id='jd4ofb7k' and e6.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
                union all
                select e0.org_id as desc_org_id, e7.id as anc_member_id from iuap_apdoc_basedoc.org_epm_orginization_ext e0 join iuap_apdoc_basedoc.org_epm_orginization_ext e1 on e1.id=e0.parent_org_id and e1.dr=0 and e1.ytenant_id='jd4ofb7k' and e1.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e2 on e2.id=e1.parent_org_id and e2.dr=0 and e2.ytenant_id='jd4ofb7k' and e2.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e3 on e3.id=e2.parent_org_id and e3.dr=0 and e3.ytenant_id='jd4ofb7k' and e3.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e4 on e4.id=e3.parent_org_id and e4.dr=0 and e4.ytenant_id='jd4ofb7k' and e4.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e5 on e5.id=e4.parent_org_id and e5.dr=0 and e5.ytenant_id='jd4ofb7k' and e5.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e6 on e6.id=e5.parent_org_id and e6.dr=0 and e6.ytenant_id='jd4ofb7k' and e6.org_epm_systems_id='2570581176914280457' join iuap_apdoc_basedoc.org_epm_orginization_ext e7 on e7.id=e6.parent_org_id and e7.dr=0 and e7.ytenant_id='jd4ofb7k' and e7.org_epm_systems_id='2570581176914280457' where e0.dr=0 and e0.ytenant_id='jd4ofb7k' and e0.org_epm_systems_id='2570581176914280457'
               ) cl
               join iuap_apdoc_basedoc.org_epm_organizations o2 on o2.id = cl.desc_org_id
               join (select z.id as org_pk, case when f.vcol46='01' then 1 else 0 end as is_legal
                       from iuap_apdoc_basedoc.org_orgs z
                       left join iuap_apdoc_basedoc.org_orgs_feature_1 f on f.id=z.characterid
                      where z.dr=0 and z.ytenant_id='jd4ofb7k') org on org.org_pk = o2.org_source_id
              group by cl.anc_member_id, org.org_pk ) t
     group by node_id ) y on y.node_id = e.id
where e.dr=0 and o.dr=0 and e.ytenant_id='jd4ofb7k' and e.org_epm_systems_id='2570581176914280457'
order by e.parent_org_id, e.id